head.script:
scwin.test_expression = function(value) {
    return value + "_test";
};
scwin.gridView1_ongroupby = function(options) {
    var flag = true;
    if (flag) {
        options.closeGroup = true;
        options.groupbyHeader = [{
            colSpan: "10",
            inputType: "expression",
            expression: " toggle() + depthStr() + ' [ '+ SUM('col3') +',' + count() + ' 건 ] ' ",
            align: "left"
        }];
        options.groupbyFooter = [{
                colSpan: "7"
            },
            {
                colSpan: "3",
                inputType: "expression",
                expression: " SUM('col3')",
                displayFormatter: "countFormatFunction",
                align: "center"
            }
        ];
        gridView1.groupby(options); //실제 groupby 실행
    } else {
        return false;
    }
};
scwin.countFormatFunction = function(value) {
    return "총판매수량 : " + value + " 개 ";
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setVal = function() {
    scwin.simulateWrapper('#gridView1_column23', 'drag-n-drop', {
        dx: 0,
        dy: -60
    });
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq('.w2grid_groupbyZone_column').length == 1;
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_value').text() == 'select';
}
scwin.checkVal3 = function() {
    return WebSquare.wUnit.getJq('#gridView1_column18').text() == '360';
}
scwin.checkVal4 = function() {
    return WebSquare.logger.getErrorLog() == '';
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 샘플파일을 실행 후 gridview의 header부분인 select항목을 마우스로 드래그하여 위로 이동시켜 groupby를 수행한다.
    //1. After running the sample file, drag the select item, which is the header part of the gridview, with mouse and move it up to perform groupby.
    //Verify step 1-1. The value of the select item will be groypby and the value of the 'name3' item ('360') will be shown in the footer (previously the value will disappear).
    WebSquare.wUnit.addCommand("set", "scwin.setVal()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 로그보기를 통해 정상로그를 확인한다.
    //2. Check the normal log through the log view.
    //Verify step 2. The normal log is displayed.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
